// Festival dates (idea #150): New Year's Day (Jan 1), the Spring Festival (Chinese New Year) and
// the Mid-Autumn Festival, for the interactive page and the live banner.
// Generated by scripts/make_holidays.mjs from the ICU Chinese calendar, every year checked
// against published dates (Wikipedia and the Hong Kong Observatory). Do not edit by hand; the
// same table is in scripts/festivals.py. Valid 2024 to 2035. The browser's own Chinese
// calendar (Intl, ICU) is not used for other years on purpose: it puts a new moon that falls
// near midnight in Beijing on the wrong day (the Spring Festival of 2027 and 2030).

export const FIRST = 2024;
export const LAST = 2035;
export const SPRING_FESTIVAL = {
  2024: '2024-02-10',
  2025: '2025-01-29',
  2026: '2026-02-17',
  2027: '2027-02-06',
  2028: '2028-01-26',
  2029: '2029-02-13',
  2030: '2030-02-03',
  2031: '2031-01-23',
  2032: '2032-02-11',
  2033: '2033-01-31',
  2034: '2034-02-19',
  2035: '2035-02-08',
};
export const MID_AUTUMN = {
  2024: '2024-09-17',
  2025: '2025-10-06',
  2026: '2026-09-25',
  2027: '2027-09-15',
  2028: '2028-10-03',
  2029: '2029-09-22',
  2030: '2030-09-12',
  2031: '2031-10-01',
  2032: '2032-09-19',
  2033: '2033-09-08',
  2034: '2034-09-27',
  2035: '2035-09-16',
};

const pad = (n) => String(n).padStart(2, '0');

/** 'new-year', 'spring-festival', 'mid-autumn' or null for a local calendar date (month 1 to 12). */
export function festivalOn(y, m, d) {
  if (m === 1 && d === 1) return 'new-year';
  const iso = `${y}-${pad(m)}-${pad(d)}`;
  if (SPRING_FESTIVAL[y] === iso) return 'spring-festival';
  if (MID_AUTUMN[y] === iso) return 'mid-autumn';
  return null;
}
